--提示
function UIActivityRoleSendLettersPanelNode:OnBtnRole()
    local isUnlock = SendWordComponent:IsUnlockReward(self._vo.id)
    if isUnlock then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityRoleLettersDialog, parameters = { id = self._vo.id } })
        --GameUtils.Toast(localize("已领取"))
        return
    end
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.unlockItem)
    if GoodsUtils.GetThingNo(self._vo.unlockItem) < checkNumber(self._vo.unlockNum) then 
        GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
        return
    end

    SendWordComponent:ActivitySendUnlockReq(self._vo.id, function()
        self:FillSelf()

        if self._cb then
            self._cb()
        end
        GoodsUtils.DrawRewards({{
            goodsId = checkNumber(self._vo.unlockItem),
            num = checkNumber(self._vo.unlockNum) * -1
        }}, true)

        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityRoleLettersDialog, parameters = { id = self._vo.id } })
    end)
end

function UIActivityRoleSendLettersPanelNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

